// Leads with what is waiting on Kelvin, and states plainly that nothing was
// sent without him. The previous version opened with four internal queue
// counts and never answered either question.
const d = $input.first().json || {};
const awaitingApproval = d.awaiting_approval != null ? d.awaiting_approval : 0;
const awaitingBuyer    = d.awaiting_buyer != null ? d.awaiting_buyer : 0;
const readyToPaste     = d.ready_to_paste != null ? d.ready_to_paste : 0;
const sendsToday       = d.sends_today != null ? d.sends_today : 0;
const cap              = d.daily_send_cap != null ? d.daily_send_cap : '?';
const parked           = d.parked_awaiting_contact != null ? d.parked_awaiting_contact : 0;

const headline = awaitingApproval === 1
  ? '1 draft awaiting your approval — nothing has been sent'
  : awaitingApproval + ' drafts awaiting your approval — nothing has been sent';

const lines = [headline, ''];
lines.push('Approve or edit them here:');
lines.push('https://ceo.thdecodedempire.com/dashboard/marketing#outreach');
lines.push('');
lines.push('Queue');
lines.push('  awaiting approval : ' + awaitingApproval);
lines.push('  awaiting a buyer  : ' + awaitingBuyer + (parked ? ' (' + parked + ' draft(s) parked until a buyer is named)' : ''));
lines.push('  ready to paste    : ' + readyToPaste);
lines.push('  sends today       : ' + sendsToday + ' / ' + cap);
// null means not measured; printing 0 would claim nobody replied.
lines.push('  replies this week : ' + (d.replies_this_week == null ? 'not measured' : d.replies_this_week));
lines.push('');
lines.push('Nothing in this pipeline sends without your approval.');

return [{ json: { subject: headline, body: lines.join('\n') } }];
